package org.openenglish.reader;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.widget.*;import android.view.*;import java.util.concurrent.*;
/** Explicit, verified model installation with a clear path back to learning. */
public final class IslandModelActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler ui=new Handler(Looper.getMainLooper());private volatile CloudClient.Job job;private TextView status,checklist,returnButton;private ProgressBar progress;private LocalModels.Spec importing;private long lastProgress;private Spinner model;private LinearLayout root;
 private int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
 private TextView label(String s,int n){TextView v=new TextView(this);v.setText(s);v.setTextSize(n);v.setTextColor(CosmicUi.INK);v.setPadding(0,dp(8),0,dp(8));root.addView(v);return v;}
 private TextView button(String s,Runnable action){TextView b=label(s,15);b.setGravity(Gravity.CENTER);b.setMinHeight(dp(52));b.setPadding(dp(12),dp(12),dp(12),dp(12));CosmicUi.button(b,false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);b.setLayoutParams(p);b.setOnClickListener(v->action.run());return b;}
 public void onCreate(Bundle b){super.onCreate(b);if(b!=null){String id=b.getString("import_model","");for(LocalModels.Spec spec:new LocalModels.Spec[]{LocalModels.QWEN,LocalModels.QWEN_SMALL,LocalModels.DEEPSEEK})if(spec.id.equals(id))importing=spec;}getWindow().setStatusBarColor(CosmicUi.BG);getWindow().setNavigationBarColor(CosmicUi.BG);ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(18),dp(22),dp(28));root.setBackgroundColor(CosmicUi.BG);sc.addView(root);android.widget.FrameLayout sky=new android.widget.FrameLayout(this);sky.addView(new CosmicUi.Sky(this),new android.widget.FrameLayout.LayoutParams(-1,-1));root.setBackgroundColor(0xdd10152c);sky.addView(sc);setContentView(sky);button("‹ 返回",this::finish);label("✦ 唤醒岛上的 AI",26);label("只要准备一位本地老师，就能开始聊天。课程示范、跟读和复习现在就能用。",15);
  checklist=label("",15);checklist.setPadding(dp(16),dp(14),dp(16),dp(14));checklist.setBackground(CosmicUi.panel(this,0xff292643,0xff1a2840,22));
  model=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Qwen 1.5B · 1.12 GB · 推荐","Qwen 0.5B · 491 MB · 轻量","DeepSeek 1.5B · 1.12 GB"});model.setAdapter(adapter);model.setBackgroundColor(0xffcbbded);root.addView(model);model.setSelection(LocalModels.islandModel(this)==LocalModels.DEEPSEEK?2:LocalModels.islandModel(this)==LocalModels.QWEN_SMALL?1:0);model.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){getSharedPreferences("language_magic",0).edit().putString("model",n==2?"deepseek":n==1?"qwen_small":"qwen").apply();if(status!=null&&job==null)refresh();}});
  button("下载 / 继续下载选中的老师",()->{LocalModels.Spec selected=LocalModels.islandModel(this);run(j->LocalModels.download(this,selected,j,this::update));});button("从手机文件导入选中模型",()->{if(job!=null){status.setText("先等当前任务结束，或停止下载");return;}importing=LocalModels.islandModel(this);Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,451);}catch(Exception e){status.setText("无法打开文件选择器");}});
  progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);root.addView(progress);status=label("",15);status.setTextIsSelectable(true);returnButton=button("",()->{if(job!=null)return;if(!LocalModels.ready(this,LocalModels.islandModel(this))){status.setText("先下载或导入所选老师；也可以直接返回练习课程。");return;}setResult(RESULT_OK);finish();});CosmicUi.button(returnButton,true);
  button("停止当前下载（保留续传进度）",()->{if(job!=null){job.cancel();status.setText("正在停止，下载进度会保留…");}});
  LinearLayout extra=new LinearLayout(this);extra.setOrientation(1);extra.setVisibility(View.GONE);button("语音设置与更多选项 ⌄",()->extra.setVisibility(extra.getVisibility()==View.GONE?View.VISIBLE:View.GONE));root.addView(extra);LinearLayout main=root;root=extra;
  button("准备内置三语 Whisper",()->run(j->LocalModels.multilingual(this,j)));button("浏览器打开选中的模型",()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(LocalModels.islandModel(this).url)));}catch(Exception e){status.setText("未找到浏览器");}});button("系统离线语音包设置",()->{try{startActivity(new Intent("com.android.settings.TTS_SETTINGS"));}catch(Exception e){status.setText("在手机设置中搜索文字转语音");}});root=main;
  label("文字聊天先准备老师，语音聊天再准备 Whisper 和麦克风。Qwen 0.5B 更省空间，表达能力较弱；DeepSeek 蒸馏版可能复述输入或夹英文。粤语识别可能转成普通话文字，可点识别结果修改。缺少系统语音时，使用内置 eSpeak，音色偏机械。",13);refresh();}
 private void refresh(){LocalModels.Spec m=LocalModels.islandModel(this);boolean ready=LocalModels.ready(this,m);long free=getFilesDir().getUsableSpace();checklist.setText("✦ 课程与跟读：已准备\n"+(ready?"✦ ":"◷ ")+"本地老师："+(ready?"已安装":"待下载或导入")+"\n✦ 三语 Whisper："+(LocalModels.ready(this,LocalModels.MULTI)?"已准备":"内置，语音聊天时解包")+"\n✦ 离线朗读：内置备用语音可用");status.setText("当前老师："+m.name+"\n可用存储约 "+String.format(java.util.Locale.US,"%.2f GB",free/1e9)+"；模型 "+String.format(java.util.Locale.US,"%.2f GB",m.bytes/1e9)+"\n完整下载另留至少 64 MB 空间，语音解包另约 149 MB。无需 API Key。");returnButton.setText(ready?(getIntent().getBooleanExtra("return_to_chat",false)?"✦ 老师已就绪 · 返回聊天":"✦ 老师已就绪 · 返回魔法岛"):"先安装一位老师，再开始聊天");returnButton.setEnabled(ready&&job==null);}
 private interface Work{void run(CloudClient.Job j)throws Exception;}
 private void run(Work w){if(job!=null){status.setText("已有任务运行，请等待或停止");return;}CloudClient.Job current=new CloudClient.Job();job=current;status.setText("正在准备…");model.setEnabled(false);returnButton.setEnabled(false);progress.setProgress(0);worker.execute(()->{String result;try{w.run(current);current.check();result="准备完成。点击上面的返回按钮，就能继续聊天。";}catch(Throwable e){result=current.cancelled()?"已取消，可继续下载。":"准备失败："+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());}final String message=result;ui.post(()->{if(isDestroyed()||job!=current)return;job=null;model.setEnabled(true);refresh();status.append("\n"+message);});});}
 private void update(String s,long n,long total){CloudClient.Job current=job;long now=SystemClock.elapsedRealtime();if(n!=total&&now-lastProgress<250)return;lastProgress=now;ui.post(()->{if(!isDestroyed()&&current!=null&&job==current&&!current.cancelled()){status.setText(s+" · "+String.format(java.util.Locale.US,"%.1f / %.1f MB",n/1e6,total/1e6));progress.setProgress(total>0?(int)(n*1000/total):0);}});}
 protected void onActivityResult(int q,int r,Intent data){super.onActivityResult(q,r,data);if(q==451&&r==RESULT_OK&&data!=null&&data.getData()!=null){LocalModels.Spec m=importing==null?LocalModels.islandModel(this):importing;run(j->LocalModels.importModel(this,m,data.getData(),j,this::update));}}
 protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(importing!=null)b.putString("import_model",importing.id);}
 protected void onDestroy(){if(job!=null)job.cancel();worker.shutdownNow();ui.removeCallbacksAndMessages(null);super.onDestroy();}
}
